Write from scratch the weights of a policy network that plays Phoenix as well as possible.

There is no training, data, loss, gradients, fine-tuning, code execution, calculator, or environment feedback. This is one response. Briefly describe the strategy and hidden units, then provide the weights in the final `edits` code block.

GAME RULES
This conversion preserves each five-stage cycle: two flocks of small horizontal/swooping birds,
two flocks of large regenerative Phoenixes, then the alien mothership. The cannon moves left and
right, fires one shot at a time, and can raise a short shield that locks movement and then has a
cooldown. Small birds pay more while low and swooping. Large birds have wings that regenerate and
a vulnerable center, with proximity scoring. The mothership requires two hits through the hull
under its cockpit and a pilot shot timed with the rotating opening.

ACTION MAPPING
0: wait
1: move left
2: unused
3: move right
4: activate force field
5: fire

INPUT CHANNEL TABLE
0: laser cannon
1: birds, bombs, and alien pilot
2: laser shot and lives
3: force field, wing-reward state, hull, and rotating opening
4: previous cannon, bird, bomb, and shot positions
5: exact cycle/stage/lives, shield timing, wing identities, step timers, hull health, opening, and rotation direction

SCORING, TERMINATION, AND HORIZON
Per cycle, the two small waves can pay `2 × 8 × 80 = 1,280`. The two large waves can pay one
20-point wing hit plus a 500-point close center kill for each of four birds, or
`2 × 4 × 520 = 4,160`. The pilot maximum begins at 4,000 and rises by 1,000 per cycle, but the
two mandatory hull shots make the reachable awards 3,800, 4,800, and 5,800. Across three cycles,
`score_cap = 3 × (1,280 + 4,160) + 3,800 + 4,800 + 5,800 = 30,720`. Normalization is
`min(max(raw_score, 0), 30_720) / 30_720`.

Actions are sampled from softmax logits and have sticky-action probability 0.1.

Exact minAtar-synth source (`minatar_synth/games/phoenix.py`):
```python
import numpy as np


class PhoenixEnvironment:
  """Three five-stage Phoenix cycles with shield and layered mothership."""

  score_cap = 30_720.0

  def __init__(self, sticky_action_prob: float = 0.1, horizon: int = 4_000):
    self.sticky_action_prob = sticky_action_prob
    self.horizon = horizon
    self.random = np.random.RandomState()
    self.seed(0)
    self.reset()

  @classmethod
  def normalize_score(cls, raw_score: float) -> float:
    return min(max(raw_score, 0.0), cls.score_cap) / cls.score_cap

  def seed(self, seed: int) -> None:
    self.random.seed(seed)

  def reset(self) -> None:
    self.cycle = 0
    self.stage = 0
    self.lives = 5
    self.score = 0.0
    self.steps = 0
    self.last_action = 0
    self.terminal = False
    self._start_stage()

  def _start_stage(self) -> None:
    self.player_column = 5
    self.previous_player_column = 5
    self.shield_timer = 0
    self.shield_cooldown = 0
    self.shot: list[int] | None = None
    self.previous_shot: list[int] | None = None
    self.bombs: list[list[int]] = []
    self.previous_bombs: list[list[int]] = []
    self.stage_steps = 0
    if self.stage < 2:
      self.enemies = [
        {"id": index, "position": [1 + index // 4, 1 + (index % 4) * 2], "direction": 1 if index % 2 == 0 else -1}
        for index in range(8)
      ]
      self.wing_rewarded: set[int] = set()
    elif self.stage < 4:
      self.enemies = [
        {"id": index, "position": [1 + index // 2, 2 + (index % 2) * 5], "direction": 1 if index % 2 == 0 else -1}
        for index in range(4)
      ]
      self.wing_rewarded = set()
    else:
      self.enemies = []
      self.hull_health = [0, 0, 2, 2, 2, 2, 2, 2, 0, 0]
      self.rotating_hole = 2
      self.rotating_direction = 1
      self.mothership_shots = 0
    self.previous_enemies = {int(enemy["id"]): list(enemy["position"]) for enemy in self.enemies}

  def act(self, action: int) -> tuple[float, bool]:
    if self.terminal:
      return 0.0, True
    if self.random.rand() < self.sticky_action_prob:
      action = self.last_action
    self.last_action = action
    self.previous_player_column = self.player_column
    self.previous_shot = None if self.shot is None else self.shot.copy()
    self.previous_bombs = [bomb.copy() for bomb in self.bombs]
    self.previous_enemies = {int(enemy["id"]): list(enemy["position"]) for enemy in self.enemies}
    if self.shield_timer == 0:
      if action == 1:
        self.player_column = max(0, self.player_column - 1)
      elif action == 3:
        self.player_column = min(9, self.player_column + 1)
      elif action == 4 and self.shield_cooldown == 0:
        self.shield_timer = 3
        self.shield_cooldown = 10
    if action == 5 and self.shot is None:
      self.shot = [7, self.player_column]
    stage_before = (self.cycle, self.stage)
    reward = self._move_shot()
    if (self.cycle, self.stage) == stage_before and not self.terminal:
      if self.stage < 4:
        self._move_birds()
      else:
        self._move_mothership()
      self._move_bombs()
      reward += self._resolve_collisions()
    self.score += reward
    self.steps += 1
    self.stage_steps += 1
    self.shield_timer = max(0, self.shield_timer - 1)
    self.shield_cooldown = max(0, self.shield_cooldown - 1)
    if self.steps >= self.horizon:
      self.terminal = True
    return reward, self.terminal

  def _move_shot(self) -> float:
    if self.shot is None:
      return 0.0
    self.shot[0] -= 1
    if self.stage < 2:
      for enemy in list(self.enemies):
        if self.shot == enemy["position"]:
          reward = 80.0 if enemy["position"][0] >= 5 else 20.0
          self.enemies.remove(enemy)
          self.shot = None
          self._advance_if_clear()
          return reward
    elif self.stage < 4:
      for enemy in list(self.enemies):
        row, column = enemy["position"]
        if self.shot[0] != row:
          continue
        if self.shot[1] == column:
          reward = float(100 + min(4, row - 1) * 100)
          self.enemies.remove(enemy)
          self.shot = None
          self._advance_if_clear()
          return reward
        if abs(self.shot[1] - column) == 1:
          reward = 0.0
          if enemy["id"] not in self.wing_rewarded:
            self.wing_rewarded.add(enemy["id"])
            reward = 20.0
          self.shot = None
          return reward
    else:
      self.mothership_shots += 1
      row, column = self.shot
      if row == 2 and self.hull_health[column] > 0:
        self.hull_health[column] -= 1
        self.shot = None
        return 0.0
      if row == 1 and column == 5 and self.hull_health[5] == 0 and self.rotating_hole == 5:
        maximum = 4_000 + self.cycle * 1_000
        reward = float(max(1_000, maximum - max(0, self.mothership_shots - 1) * 100))
        self.shot = None
        self._advance_stage()
        return reward
    if self.shot is not None and self.shot[0] < 0:
      self.shot = None
    return 0.0

  def _move_birds(self) -> None:
    for enemy in self.enemies:
      row, column = enemy["position"]
      if self.stage_steps % max(1, 3 - self.cycle) == 0:
        column += enemy["direction"]
        if column <= 0 or column >= 9:
          enemy["direction"] *= -1
          column = min(9, max(0, column))
          row = min(7, row + 1)
      enemy["position"] = [row, column]
      if (self.stage_steps + enemy["id"]) % max(5, 12 - self.cycle * 2) == 0:
        self.bombs.append([row + 1, column])

  def _move_mothership(self) -> None:
    if self.stage_steps % 2 == 0:
      self.rotating_hole += self.rotating_direction
      if self.rotating_hole in (2, 7):
        self.rotating_direction *= -1
    interval = max(3, 8 - self.cycle * 2)
    if self.stage_steps % interval == 0:
      self.bombs.append([2, int(self.random.randint(2, 8))])

  def _move_bombs(self) -> None:
    for bomb in list(self.bombs):
      bomb[0] += 1
      if bomb[0] > 8:
        self.bombs.remove(bomb)

  def _resolve_collisions(self) -> float:
    reward = 0.0
    for enemy in list(self.enemies):
      if enemy["position"] != [8, self.player_column]:
        continue
      if self.shield_timer:
        reward += self._shield_bird_value(enemy)
        self.enemies.remove(enemy)
        self._advance_if_clear()
      else:
        self._lose_life()
      break
    for bomb in list(self.bombs):
      if bomb != [8, self.player_column]:
        continue
      self.bombs.remove(bomb)
      if not self.shield_timer:
        self._lose_life()
      break
    return reward

  def _shield_bird_value(self, enemy: dict[str, object]) -> float:
    if self.stage < 2:
      return 80.0
    return 500.0

  def _advance_if_clear(self) -> None:
    if not self.enemies:
      self._advance_stage()

  def _advance_stage(self) -> None:
    self.stage += 1
    if self.stage >= 5:
      self.stage = 0
      self.cycle += 1
    if self.cycle >= 3:
      self.terminal = True
    else:
      self._start_stage()

  def _lose_life(self) -> None:
    self.lives -= 1
    if self.lives <= 0:
      self.terminal = True
    else:
      self.player_column = 5
      self.shield_timer = 0
      self.shield_cooldown = 0
      self.shot = None
      self.bombs.clear()

  def state(self) -> np.ndarray:
    state = np.zeros((10, 10, 6), dtype=bool)
    state[8, self.player_column, 0] = True
    state[8, self.previous_player_column, 4] = True
    for enemy in self.enemies:
      row, column = enemy["position"]
      state[row, column, 1] = True
      state[*self.previous_enemies[int(enemy["id"])], 4] = True
      if self.stage >= 2:
        state[row, max(0, column - 1) : min(10, column + 2), 1] = True
        if enemy["id"] in self.wing_rewarded:
          state[row, column, 3] = True
    for bomb in self.bombs:
      state[*bomb, 1] = True
    for bomb in self.previous_bombs:
      state[*bomb, 4] = True
    if self.shot is not None:
      state[*self.shot, 2] = True
    if self.previous_shot is not None:
      state[*self.previous_shot, 4] = True
    if self.stage == 4:
      for column in range(2, 8):
        if self.hull_health[column]:
          state[2, column, 3] = True
      state[1, 5, 1] = True
      state[3, self.rotating_hole, 3] = True
    if self.shield_timer:
      state[7:10, max(0, self.player_column - 1) : min(10, self.player_column + 2), 3] = True
    state[9, : self.lives, 2] = True
    for bit in range(2):
      state[0, bit, 5] = bool(self.cycle & (1 << bit))
    for bit in range(3):
      state[0, 2 + bit, 5] = bool(self.stage & (1 << bit))
      state[0, 5 + bit, 5] = bool(self.lives & (1 << bit))
    for bit in range(4):
      state[1, bit, 5] = bool(self.shield_cooldown & (1 << bit))
      state[1, 4 + bit, 5] = bool(self.shield_timer & (1 << bit))
    for index in self.wing_rewarded:
      state[2, index, 5] = True
    for bit in range(12):
      state[3 + bit // 10, bit % 10, 5] = bool(self.steps & (1 << bit))
      state[5 + bit // 10, bit % 10, 5] = bool(self.stage_steps & (1 << bit))
    if self.stage == 4:
      for column in range(2, 8):
        for bit in range(2):
          state[7 + bit, column, 5] = bool(self.hull_health[column] & (1 << bit))
      state[9, self.rotating_hole, 5] = True
      state[9, 8, 5] = self.rotating_direction > 0
    return state

```

Input: a row-major 10x10x6 binary grid. Index `(row * 10 + column) * 6 + channel`. Channels: listed explicitly in the task-specific input channel table above.

Network: `h1=tanh(x@W1+b1)`, `h2=tanh(h1@W2+b2)`, `logits=h2@W3+b3`. Shapes are W1 600x32, b1 32, W2 32x32, b2 32, W3 32x6, b3 6. All 20,486 values start at zero.

The hidden evaluator runs 1,000 fixed-seed episodes, stopping each after 10,000 steps. It divides mean game score by the game's fixed cap and clips the result to [0, 1].

The final fenced block must start with `edits`. It may contain numeric assignments to indexed entries or slices of W1, b1, W2, b2, W3, and b3. Half-open Python slices and numeric lists are supported, as are `*=`, `+=`, and `-=`. Values must be finite and have absolute value at most 1e6. Example:
```edits
W1[12, 0] = 2.5
b1[0:4] = -1
W2[0:2, 0:3] = [[1, -1, 0.5], [0, 2, 0]]
W3[:, 2] *= 2
```

Write from scratch the weights of a policy network that plays Kung Fu Master as well as possible.

There is no training, data, loss, gradients, fine-tuning, code execution, calculator, or environment feedback. This is one response. Briefly describe the strategy and hidden units, then provide the weights in the final `edits` code block.

GAME RULES
This conversion preserves the five-floor temple climb and its faster repeat after Princess
Victoria's rescue. Thomas moves left and right, jumps over low attacks, squats under high attacks,
and uses action 5 to strike in his current stance and facing direction. Adjacent attacks are
punches; two-cell attacks are kicks, retaining the manual's different punch/kick values. Midgets
require low attacks, knife throwers require two hits, dragon balls and moths have their distinct
values, and snakes remain indestructible and must be jumped.

Henchmen can grab Thomas and drain energy until alternating left/right inputs break the hold.
Knife throwers alternate high and low projectiles. Each floor ends with its energy-bearing boss:
Fist Fighter, Boomerang Thrower, Giant Kicker, Lightning Magician, then Gang Master. A floor reset
restores the 300-unit timer and ten energy. Boss defeat awards its listed value plus
`remaining timer × 10` and `remaining energy × 100`. Timer or energy exhaustion costs one of three
lives; reaching 75,000 points awards one extra life.

ACTION MAPPING
0: hold/stand
1: move left or shake grab left
2: jump
3: move right or shake grab right
4: squat/prepare low attack
5: punch or kick in current stance/facing

INPUT CHANNEL TABLE
0: Thomas
1: enemies, low knives, bosses, and boss projectiles
2: knife throwers, dragon balls, and high knives
3: midgets and dragon balls
4: previous Thomas/knife positions, moths, and snakes
5: current-floor reward identities, enemy/boss cooldowns, floor, climb, lives, energy, exact timer, exact episode/floor steps, stance, facing, grab identity, boss health, and extra-life state

SCORING, TERMINATION, AND HORIZON
Using each regular enemy's higher attack value, floors one through five contain at most 2,000,
2,000, 7,200, 3,600, and 2,600 points, totaling 17,400 per climb. The five bosses total 23,000.
Each floor can additionally award at most `300 × 10 + 10 × 100 = 4,000`, or 20,000 per climb.
Thus one climb is bounded by 60,400 and two climbs give `score_cap = 120,800`. Normalization is
`min(max(raw_score, 0), 120_800) / 120_800`.

Actions are sampled from softmax logits and have sticky-action probability 0.1.

Exact minAtar-synth source (`minatar_synth/games/kung_fu_master.py`):
```python
import numpy as np


BOSS_NAMES = ("fist_fighter", "boomerang_thrower", "giant_kicker", "lightning_magician", "gang_master")
BOSS_VALUES = (2_000, 3_000, 3_000, 5_000, 10_000)
REGULAR_ROSTERS = (
  ("henchman",) * 4 + ("knife_thrower",) * 2,
  ("henchman",) * 3 + ("midget",) * 3 + ("knife_thrower",),
  ("dragon_ball",) * 3 + ("snake",) * 2 + ("moth",) * 2,
  ("moth",) * 3 + ("knife_thrower",) * 2 + ("henchman",) * 2,
  ("henchman",) * 4 + ("knife_thrower",) * 2 + ("midget",) * 2,
)
ENEMY_VALUES = {
  "henchman": (100, 100),
  "knife_thrower": (500, 800),
  "midget": (200, 300),
  "dragon_ball": (2_000, 2_000),
  "moth": (500, 600),
  "snake": (0, 0),
}
ENEMY_HEALTH = {"henchman": 1, "knife_thrower": 2, "midget": 1, "dragon_ball": 1, "moth": 1, "snake": 99}


class KungFuMasterEnvironment:
  """Two five-floor temple climbs with stance-sensitive combat."""

  score_cap = 120_800.0

  def __init__(self, sticky_action_prob: float = 0.1, horizon: int = 4_000):
    self.sticky_action_prob = sticky_action_prob
    self.horizon = horizon
    self.random = np.random.RandomState()
    self.seed(0)
    self.reset()

  @classmethod
  def normalize_score(cls, raw_score: float) -> float:
    return min(max(raw_score, 0.0), cls.score_cap) / cls.score_cap

  def seed(self, seed: int) -> None:
    self.random.seed(seed)

  def reset(self) -> None:
    self.climb = 0
    self.floor = 0
    self.lives = 3
    self.score = 0.0
    self.bonus_life_awarded = False
    self.steps = 0
    self.last_action = 0
    self.terminal = False
    self.claimed: set[tuple[int, int, int]] = set()
    self._start_floor()

  def _start_floor(self) -> None:
    self.player = [5, 5]
    self.previous_player = self.player.copy()
    self.facing = 1
    self.energy = 10
    self.timer = 300
    self.jump_timer = 0
    self.squat_timer = 0
    self.grabbed_by: int | None = None
    self.last_escape_direction = 0
    self.enemies: dict[int, dict[str, object]] = {}
    for index, kind in enumerate(REGULAR_ROSTERS[self.floor]):
      if (self.climb, self.floor, index) not in self.claimed:
        side = 9 if index % 2 == 0 else 0
        row = 4 if kind == "moth" else 5
        self.enemies[index] = {
          "kind": kind,
          "position": [row, side],
          "health": ENEMY_HEALTH[kind],
          "cooldown": index % 4,
          "direction": -1 if side == 9 else 1,
        }
    self.knives: list[dict[str, object]] = []
    self.previous_knives: list[list[int]] = []
    self.boss: dict[str, object] | None = None
    self.boss_projectiles: list[list[int]] = []
    self.floor_steps = 0

  def act(self, action: int) -> tuple[float, bool]:
    if self.terminal:
      return 0.0, True
    if self.random.rand() < self.sticky_action_prob:
      action = self.last_action
    self.last_action = action
    self.previous_player = self.player.copy()
    floor_before = (self.climb, self.floor)
    lives_before = self.lives
    self._apply_stance_and_movement(action)
    reward = self._attack() if action == 5 else 0.0
    self._move_regular_enemies()
    self._move_knives()
    self._move_boss()
    self._resolve_damage()
    if self.lives != lives_before or self.terminal:
      return self._finish_step(reward, consume_timer=False)
    if not self.enemies and self.boss is None:
      self._spawn_boss()
    transitioned = (self.climb, self.floor) != floor_before
    return self._finish_step(reward, consume_timer=not transitioned)

  def _finish_step(self, reward: float, consume_timer: bool = True) -> tuple[float, bool]:
    self.score += reward
    if self.score >= 75_000 and not self.bonus_life_awarded:
      self.lives = min(9, self.lives + 1)
      self.bonus_life_awarded = True
    if consume_timer:
      self.timer -= 1
      self.floor_steps += 1
      self.jump_timer = max(0, self.jump_timer - 1)
      self.squat_timer = max(0, self.squat_timer - 1)
      if self.timer <= 0:
        self._lose_life()
    self.steps += 1
    if self.steps >= self.horizon:
      self.terminal = True
    return reward, self.terminal

  def _apply_stance_and_movement(self, action: int) -> None:
    if self.grabbed_by is not None:
      direction = -1 if action == 1 else 1 if action == 3 else 0
      if direction and direction != self.last_escape_direction:
        self.last_escape_direction = direction
        enemy = self.enemies.get(self.grabbed_by)
        if enemy is not None:
          enemy["health"] = int(enemy["health"]) - 1
          if enemy["health"] <= -2:
            self.grabbed_by = None
      return
    if action == 1:
      self.player[1] = max(0, self.player[1] - 1)
      self.facing = -1
    elif action == 3:
      self.player[1] = min(9, self.player[1] + 1)
      self.facing = 1
    elif action == 2:
      self.jump_timer = 2
      self.player[0] = 3
    elif action == 4:
      self.squat_timer = 2
      self.player[0] = 6
    elif self.jump_timer == 0 and self.squat_timer == 0:
      self.player[0] = 5

  def _attack(self) -> float:
    if self.jump_timer > 0:
      return 0.0
    low = self.squat_timer > 0
    candidates = []
    for index, enemy in self.enemies.items():
      position = enemy["position"]
      distance = abs(position[1] - self.player[1])
      correct_side = int(np.sign(position[1] - self.player[1])) == self.facing
      height_ok = low if enemy["kind"] == "midget" else not low
      if correct_side and distance <= 2 and height_ok:
        candidates.append((distance, index, enemy))
    if candidates:
      distance, index, enemy = min(candidates)
      if enemy["kind"] == "snake":
        return 0.0
      enemy["health"] = int(enemy["health"]) - 1
      if enemy["health"] <= 0:
        del self.enemies[index]
        self.claimed.add((self.climb, self.floor, index))
        kick_value, punch_value = ENEMY_VALUES[str(enemy["kind"])]
        return float(kick_value if distance == 2 else punch_value)
      return 0.0
    if self.boss is not None:
      distance = abs(self.boss["position"][1] - self.player[1])
      correct_side = int(np.sign(self.boss["position"][1] - self.player[1])) == self.facing
      if correct_side and distance <= 2:
        self.boss["health"] = int(self.boss["health"]) - 1
        if self.boss["health"] <= 0:
          return self._complete_floor()
    return 0.0

  def _move_regular_enemies(self) -> None:
    interval = max(1, 3 - self.climb)
    for index, enemy in list(self.enemies.items()):
      kind = str(enemy["kind"])
      position = enemy["position"]
      if kind == "snake":
        position[1] += int(enemy["direction"])
        if not 0 <= position[1] < 10:
          del self.enemies[index]
        continue
      enemy["cooldown"] = int(enemy["cooldown"]) - 1
      if kind == "knife_thrower" and enemy["cooldown"] <= 0:
        height = "high" if (index + self.floor_steps) % 2 else "low"
        self.knives.append(
          {"position": position.copy(), "direction": int(np.sign(self.player[1] - position[1])) or -1, "height": height}
        )
        enemy["cooldown"] = max(3, 7 - self.climb)
      if self.floor_steps % interval:
        continue
      if kind == "moth":
        position[0] = 4 if position[0] == 5 else 5
      position[1] += int(np.sign(self.player[1] - position[1]))
      if kind == "snake" and position[1] == self.player[1]:
        direction = -1 if position[1] > 0 else 1
        position[1] += direction

  def _move_knives(self) -> None:
    self.previous_knives = [list(knife["position"]) for knife in self.knives]
    for knife in list(self.knives):
      knife["position"][1] += int(knife["direction"])
      if not 0 <= knife["position"][1] < 10:
        self.knives.remove(knife)

  def _spawn_boss(self) -> None:
    self.boss = {
      "kind": BOSS_NAMES[self.floor],
      "position": [5, 8],
      "health": 4 + self.floor + self.climb,
      "cooldown": 3,
    }

  def _move_boss(self) -> None:
    if self.boss is None:
      return
    self.boss["cooldown"] = int(self.boss["cooldown"]) - 1
    if self.boss["cooldown"] <= 0:
      self.boss_projectiles.append(self.boss["position"].copy())
      self.boss["cooldown"] = max(2, 6 - self.floor // 2 - self.climb)
    if self.floor_steps % 2 == 0:
      self.boss["position"][1] += int(np.sign(self.player[1] - self.boss["position"][1]))
    for projectile in list(self.boss_projectiles):
      projectile[1] += int(np.sign(self.player[1] - projectile[1]))
      if not 0 <= projectile[1] < 10:
        self.boss_projectiles.remove(projectile)

  def _resolve_damage(self) -> None:
    for index, enemy in self.enemies.items():
      if enemy["position"] != self.player:
        continue
      if enemy["kind"] == "henchman" and self.grabbed_by is None:
        self.grabbed_by = index
      self.energy -= 1
      break
    for knife in list(self.knives):
      if knife["position"][1] != self.player[1]:
        continue
      avoided = (knife["height"] == "low" and self.jump_timer > 0) or (
        knife["height"] == "high" and self.squat_timer > 0
      )
      if not avoided:
        self.energy -= 2
      self.knives.remove(knife)
    if self.boss is not None and self.boss["position"] == self.player:
      self.energy -= 3
    for projectile in list(self.boss_projectiles):
      if projectile[1] == self.player[1]:
        self.energy -= 2
        self.boss_projectiles.remove(projectile)
    if self.grabbed_by is not None:
      self.energy -= 1
    if self.energy <= 0:
      self._lose_life()

  def _complete_floor(self) -> float:
    reward = float(BOSS_VALUES[self.floor] + self.timer * 10 + self.energy * 100)
    self.floor += 1
    if self.floor >= 5:
      self.floor = 0
      self.climb += 1
    if self.climb >= 2:
      self.terminal = True
    else:
      self._start_floor()
    return reward

  def _lose_life(self) -> None:
    self.lives -= 1
    if self.lives <= 0:
      self.terminal = True
    else:
      self._start_floor()

  def state(self) -> np.ndarray:
    state = np.zeros((10, 10, 6), dtype=bool)
    state[*self.player, 0] = True
    for enemy in self.enemies.values():
      state[*enemy["position"], 1] = True
      kind = str(enemy["kind"])
      if kind in ("knife_thrower", "dragon_ball"):
        state[*enemy["position"], 2] = True
      if kind in ("midget", "dragon_ball"):
        state[*enemy["position"], 3] = True
      if kind in ("moth", "snake"):
        state[*enemy["position"], 4] = True
    if self.boss is not None:
      state[*self.boss["position"], 1] = True
    for knife in self.knives:
      state[*knife["position"], 2 if knife["height"] == "high" else 1] = True
    for projectile in self.boss_projectiles:
      state[*projectile, 1] = True
    state[*self.previous_player, 4] = True
    for knife in self.previous_knives:
      state[*knife, 4] = True
    for index in range(len(REGULAR_ROSTERS[self.floor])):
      state[index // 10, index % 10, 5] = (self.climb, self.floor, index) in self.claimed
    state[2, self.floor, 5] = True
    state[2, 5 + self.climb, 5] = True
    for bit in range(4):
      state[3, bit, 5] = bool(self.lives & (1 << bit))
      state[3, 4 + bit, 5] = bool(self.energy & (1 << bit))
    for bit in range(9):
      state[4, bit, 5] = bool(self.timer & (1 << bit))
    for bit in range(12):
      state[5 + bit // 10, bit % 10, 5] = bool(self.steps & (1 << bit))
    state[7, 0, 5] = self.facing > 0
    state[7, 1 : 1 + self.jump_timer, 5] = True
    state[7, 3 : 3 + self.squat_timer, 5] = True
    state[7, 5, 5] = self.grabbed_by is not None
    if self.grabbed_by is not None:
      for bit in range(4):
        state[7, 6 + bit, 5] = bool(self.grabbed_by & (1 << bit))
    if self.boss is not None:
      for bit in range(4):
        state[8, bit, 5] = bool(int(self.boss["health"]) & (1 << bit))
      for bit in range(3):
        state[8, 4 + bit, 5] = bool(int(self.boss["cooldown"]) & (1 << bit))
    state[8, 7, 5] = self.bonus_life_awarded
    knife_throwers = [enemy for enemy in self.enemies.values() if enemy["kind"] == "knife_thrower"]
    for index, enemy in enumerate(knife_throwers[:2]):
      for bit in range(3):
        state[1, index * 3 + bit, 5] = bool(int(enemy["cooldown"]) & (1 << bit))
    for bit in range(10):
      state[9, bit, 5] = bool(self.floor_steps & (1 << bit))
    for bit in range(2):
      state[8, 8 + bit, 5] = bool(self.floor_steps & (1 << (10 + bit)))
    return state

