    reward = self._collect_fruit_and_ring_bell()
    if action == 5:
      reward += self._punch()
    self._spawn_apples()
    self._move_monkeys()
    self._move_apples()
    self._resolve_contacts(action)
    if self.lives != lives_before or self.terminal:
